import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

interface SignedIn {
  name: string;
  locale: string;
}

/** How the screen shows a user figures: en 1234.56, de 1.234,56. */
export type Locale = 'en' | 'de';
export const LOCALES: readonly Locale[] = ['en', 'de'];

function toLocale(value: string | null | undefined): Locale {
  return value === 'de' ? 'de' : 'en';
}

/** The people-list columns a user may switch off on their screen, in the order the chooser lists them. */
export const PERSON_COLUMNS = [
  'claimed', 'due-total', 'excess', 'statement-count', 'stated-total', 'statement-date', 'overdue-count',
  'overdue-total', 'patrons', 'backing', 'hold', 'retired', 'terms', 'contact', 'aliases',
] as const;
export type PersonColumn = (typeof PERSON_COLUMNS)[number];

interface SheetView {
  id: string;
  today: string;
  archived: boolean;
  parent: string | null;
}

// Who is signed in and which sheet is active. Everything else in the app is kept per sheet.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  /** The signed-in user's locale, kept per user in the store; en unless chosen. */
  readonly locale = signal<Locale>('en');
  /** The people-list columns the signed-in user's screen leaves out, kept per user in the store. */
  readonly hiddenColumns = signal<ReadonlySet<string>>(new Set());
  /** Column choices are written one after another, so the store ends with the last one made. */
  private columnWrites: Promise<unknown> = Promise.resolve();
  readonly sheetId = signal<string | null>(null);
  /** The active sheet's today (yyyy-mm-dd) as the store holds it. */
  readonly sheetToday = signal<string | null>(null);
  /** The day (yyyy-mm-dd) this user's screen shows every sheet as it stood at the end of; null when
   *  it shows the sheet as it is now. While it is set every change is refused. */
  readonly asOf = signal<string | null>(null);
  /** The day every date decision and default date uses: the as-of day when one is set, or else the
   *  sheet's today. */
  readonly today = computed(() => this.asOf() ?? this.sheetToday());
  /** Whether the active sheet is archived: it stays visible and refuses every change. */
  readonly archived = signal(false);
  /** The active sheet's parent's id; null when it has none. */
  readonly parent = signal<string | null>(null);
  /** The sheet whose people and claims are on screen: set once a load of them has been read, so the
   *  sheet shows as loaded only when its rows are there to act on. */
  readonly shownId = signal<string | null>(null);
  /** Bumped on every sheet load, so what is kept per sheet is re-read from the store. */
  readonly loads = signal(0);

  async signIn(name: string): Promise<void> {
    const res = await firstValueFrom(this.http.post<SignedIn>('/api/signin', { name }));
    this.user.set(res.name);
    this.locale.set(toLocale(res.locale));
    this.hiddenColumns.set(new Set());
    this.sheetId.set(null);
    this.shownId.set(null);
    this.sheetToday.set(null);
    this.asOf.set(null);
    this.archived.set(false);
    this.parent.set(null);
  }

  /** Whether a sheet load is under way: its rows are read again once it is done, so a read
   *  finished meanwhile does not show the sheet as loaded. */
  private loading = false;

  /** Record that the sheet's people and claims, as read for its latest load, are on screen. */
  markShown(id: string): void {
    if (!this.loading && this.sheetId() === id) this.shownId.set(id);
  }

  /** Load a sheet by id; one never loaded before starts empty. */
  async loadSheet(id: string): Promise<void> {
    const user = this.user();
    if (!user) throw new Error('not signed in');
    this.loading = true;
    try {
      const res = await firstValueFrom(
        this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null, {
          headers: { 'X-User': user },
        }),
      );
      this.show(res);
      await this.readLocale(user);
      await this.readColumns(user);
    } finally {
      this.loading = false;
    }
    this.bumpLoads();
  }

  /** Choose the signed-in user's locale; it is kept for them across every sheet. */
  async setLocale(locale: Locale): Promise<void> {
    const user = this.user();
    if (!user) throw new Error('not signed in');
    const res = await firstValueFrom(
      this.http.put<{ locale: string }>('/api/me/locale', { locale }, { headers: { 'X-User': user } }),
    );
    this.locale.set(toLocale(res.locale));
  }

  /** Re-read the user's locale from the store, as another screen of theirs may have changed it. */
  private async readLocale(user: string): Promise<void> {
    const res = await firstValueFrom(
      this.http.get<{ locale: string }>('/api/me/locale', { headers: { 'X-User': user } }),
    );
    this.locale.set(toLocale(res.locale));
  }

  /** Switch a people-list column on or off on the signed-in user's screen; kept for them across sheets. */
  async setColumnShown(column: PersonColumn, shown: boolean): Promise<void> {
    const user = this.user();
    if (!user) throw new Error('not signed in');
    const hidden = new Set(this.hiddenColumns());
    if (shown) hidden.delete(column);
    else hidden.add(column);
    this.hiddenColumns.set(hidden);
    const write = this.columnWrites.catch(() => undefined).then(() =>
      firstValueFrom(
        this.http.put<{ hidden: string[] }>('/api/me/columns', { hidden: [...hidden] }, { headers: { 'X-User': user } }),
      ),
    );
    this.columnWrites = write;
    await write;
  }

  /** Re-read the user's column choice from the store, once any of theirs still being written is in. */
  private async readColumns(user: string): Promise<void> {
    await this.columnWrites.catch(() => undefined);
    const res = await firstValueFrom(
      this.http.get<{ hidden: string[] }>('/api/me/columns', { headers: { 'X-User': user } }),
    );
    this.hiddenColumns.set(new Set(res.hidden));
  }

  /** Change the active sheet's today. */
  async setToday(today: string): Promise<void> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) throw new Error('no sheet loaded');
    const res = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }, {
        headers: { 'X-User': user },
      }),
    );
    this.show(res);
  }

  /** Archive the active sheet (a steward only). */
  async archive(): Promise<void> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) throw new Error('no sheet loaded');
    const res = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null, {
        headers: { 'X-User': user },
      }),
    );
    this.show(res);
  }

  /** Clone the active sheet to another id, never used before (a steward only); the id cloned to. */
  async cloneSheet(to: string): Promise<string> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) throw new Error('no sheet loaded');
    const res = await firstValueFrom(
      this.http.post<{ to: string }>(`/api/sheets/${encodeURIComponent(id)}/clone`, { to }, {
        headers: { 'X-User': user },
      }),
    );
    return res.to;
  }

  /** Show every sheet as it stood at the end of a day (null: as it is now), re-reading it. */
  setAsOf(day: string | null): void {
    this.asOf.set(day);
    this.bumpLoads();
  }

  private show(sheet: SheetView): void {
    this.sheetId.set(sheet.id);
    this.sheetToday.set(sheet.today);
    this.archived.set(sheet.archived);
    this.parent.set(sheet.parent);
  }

  private bumpLoads(): void {
    this.loads.update((n) => n + 1);
  }
}
import { Component, effect, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { LOCALES, Locale, Session } from '../../core/session';

// The signed-in name, and the form that loads a sheet by id.
@Component({
  selector: 'app-sheet-bar',
  imports: [ReactiveFormsModule],
  template: `
    <p>Signed in as <strong data-testid="current-user">{{ session.user() }}</strong></p>
    <form data-testid="user-locale-form" [formGroup]="localeForm" (ngSubmit)="saveLocale()">
      <label for="user-locale">Your locale</label>
      <select id="user-locale" data-testid="user-locale" formControlName="locale">
        @for (l of locales; track l) {
          <option [value]="l">{{ l }}</option>
        }
      </select>
      <button type="submit" data-testid="user-locale-save">Save locale</button>
      @if (localeError()) {
        <p role="alert" data-testid="user-locale-error">{{ localeError() }}</p>
      }
    </form>
    <p>Locale: <strong data-testid="user-locale-current">{{ session.locale() }}</strong></p>
    <form data-testid="sheet-form" [formGroup]="form" (ngSubmit)="load()">
      <label for="sheet-id-input">Sheet id</label>
      <input id="sheet-id-input" data-testid="sheet-id-input" formControlName="sheetId" />
      <button type="submit" data-testid="sheet-load">Load sheet</button>
      @if (error()) {
        <p role="alert" data-testid="sheet-load-error">{{ error() }}</p>
      }
    </form>
    <p>Sheet: <strong data-testid="sheet-current-id">{{ session.shownId() ?? '' }}</strong></p>
    @if (session.sheetId()) {
      <p>Today: <strong data-testid="sheet-today">{{ session.sheetToday() ?? '' }}</strong></p>
      <form data-testid="sheet-today-form" [formGroup]="todayForm" (ngSubmit)="saveToday()">
        <label for="sheet-today-input">Sheet's today</label>
        <input id="sheet-today-input" type="date" data-testid="sheet-today-input" formControlName="today" />
        <button type="submit" data-testid="sheet-today-save">Set today</button>
      </form>
      <p>Archived: <strong data-testid="sheet-archived">{{ session.archived() ? 'yes' : 'no' }}</strong></p>
      <p>Parent sheet: <strong data-testid="sheet-parent">{{ session.parent() ?? '' }}</strong></p>
      <button type="button" data-testid="sheet-archive" (click)="archive()">Archive sheet</button>
      <form data-testid="sheet-clone-form" [formGroup]="cloneForm" (ngSubmit)="cloneSheet()">
        <label for="sheet-clone-to">Clone the sheet to id</label>
        <input id="sheet-clone-to" data-testid="sheet-clone-to" formControlName="to" />
        <button type="submit" data-testid="sheet-clone">Clone sheet</button>
      </form>
      <p>Cloned to: <strong data-testid="sheet-cloned-to">{{ clonedTo() }}</strong></p>
      @if (sheetError()) {
        <p role="alert" data-testid="sheet-error">{{ sheetError() }}</p>
      }
      <form data-testid="asof-form" [formGroup]="asOfForm" (ngSubmit)="setAsOf()">
        <label for="asof-date">Show the sheet as of</label>
        <input id="asof-date" type="date" data-testid="asof-date" formControlName="day" />
        <button type="submit" data-testid="asof-set">Set as of</button>
        <button type="button" data-testid="asof-clear" (click)="clearAsOf()">Clear as of</button>
        @if (asOfError()) {
          <p role="alert" data-testid="asof-error">{{ asOfError() }}</p>
        }
      </form>
      <p>As of: <strong data-testid="sheet-asof">{{ session.asOf() ?? '' }}</strong></p>
    }
  `,
})
export class SheetBar {
  protected readonly session = inject(Session);
  protected readonly form = new FormGroup({ sheetId: new FormControl('', { nonNullable: true }) });
  protected readonly error = signal('');
  protected readonly todayForm = new FormGroup({ today: new FormControl('', { nonNullable: true }) });
  protected readonly sheetError = signal('');
  protected readonly cloneForm = new FormGroup({ to: new FormControl('', { nonNullable: true }) });
  /** The id the sheet was last cloned to from this screen; blank while a clone runs. */
  protected readonly clonedTo = signal('');
  protected readonly asOfForm = new FormGroup({ day: new FormControl('', { nonNullable: true }) });
  protected readonly asOfError = signal('');
  protected readonly locales = LOCALES;
  protected readonly localeForm = new FormGroup({
    locale: new FormControl<Locale>(this.session.locale(), { nonNullable: true }),
  });
  protected readonly localeError = signal('');

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    this.todayForm.valueChanges.subscribe(() => this.sheetError.set(''));
    this.asOfForm.valueChanges.subscribe(() => this.asOfError.set(''));
    this.cloneForm.valueChanges.subscribe(() => this.sheetError.set(''));
    this.localeForm.valueChanges.subscribe(() => this.localeError.set(''));
    // The select shows the locale the store holds for this user, re-read on every sheet load.
    effect(() => this.localeForm.controls.locale.setValue(this.session.locale(), { emitEvent: false }));
  }

  async saveLocale(): Promise<void> {
    this.localeError.set('');
    try {
      await this.session.setLocale(this.localeForm.controls.locale.value);
    } catch {
      this.localeError.set('The locale could not be saved.');
    }
  }

  /** Show the sheet, on this screen only, as it stood at the end of the day entered. */
  setAsOf(): void {
    this.asOfError.set('');
    this.sheetError.set('');
    const day = this.asOfForm.controls.day.value.trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) {
      this.asOfError.set('Enter a date to show the sheet as of.');
      return;
    }
    this.session.setAsOf(day);
  }

  /** Show the sheet as it is now again. */
  clearAsOf(): void {
    this.asOfError.set('');
    this.sheetError.set('');
    this.asOfForm.controls.day.setValue('', { emitEvent: false });
    this.session.setAsOf(null);
  }

  async load(): Promise<void> {
    this.error.set('');
    const id = this.form.controls.sheetId.value.trim();
    if (!id) {
      this.error.set('Enter a sheet id to load.');
      return;
    }
    this.sheetError.set('');
    try {
      await this.session.loadSheet(id);
    } catch {
      this.error.set('The sheet could not be loaded.');
    }
  }

  async saveToday(): Promise<void> {
    this.sheetError.set('');
    const today = this.todayForm.controls.today.value.trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      this.sheetError.set('Enter a date for the sheet\'s today.');
      return;
    }
    try {
      await this.session.setToday(today);
    } catch {
      this.sheetError.set('The sheet\'s today could not be changed.');
    }
  }

  async archive(): Promise<void> {
    this.sheetError.set('');
    try {
      await this.session.archive();
    } catch {
      this.sheetError.set('The sheet could not be archived.');
    }
  }

  async cloneSheet(): Promise<void> {
    this.sheetError.set('');
    this.clonedTo.set('');
    const to = this.cloneForm.controls.to.value.trim();
    if (!to) {
      this.sheetError.set('Enter a sheet id to clone to.');
      return;
    }
    try {
      this.clonedTo.set(await this.session.cloneSheet(to));
    } catch {
      this.sheetError.set('The sheet could not be cloned.');
    }
  }
}
